#pragma once

// The Prepare header's machine chip: printer on the left, filament on the
// right, one outline around both.
//
// The halves are two HeaderButtons rather than one control with two hit
// regions, so each gets its own hover, pressed, focus and open state for free,
// and each can anchor its own menu. Left and right arrow keys move between
// them, so the chip behaves like one control to the keyboard while remaining
// two to the pointer.
//
// The chip renders state and raises intent. It reads nothing and changes
// nothing in Orca; StatusRow owns both. It states facts and never warns.

#include "FilamentChipModel.hpp"
#include "HeaderControls.hpp"

#include <wx/panel.h>
#include <wx/string.h>

#include <functional>

namespace Slic3r::GUI::JusPrin {

class PrinterFilamentChip : public wxPanel
{
public:
    PrinterFilamentChip(wxWindow* parent, const ShellTheme& theme);

    // Left half. `nozzle` is already formatted for display; `tooltip` is the
    // full text the half may ellipsize.
    void set_printer(const wxString& nickname, const wxString& nozzle, const wxString& tooltip);
    // Right half: the slot dots and label the model describes. `label` is the
    // text the model resolved to -- a short name or a count.
    void set_filaments(const FilamentChipModel& model, const wxString& label, const wxString& tooltip);

    void set_dark(bool dark);

    // Raised when a half is activated, by pointer or keyboard.
    void on_printer_activated(std::function<void()> handler) { m_printer_activated = std::move(handler); }
    void on_filament_activated(std::function<void()> handler) { m_filament_activated = std::move(handler); }

    HeaderButton& printer_half() { return *m_printer; }
    HeaderButton& filament_half() { return *m_filament; }

    wxSize DoGetBestSize() const override;
    // The whole chip as one image: both halves drawn side by side exactly as
    // they sit in the header.
    wxBitmap snapshot();

private:
    void layout();

    HeaderButton* m_printer{nullptr};
    HeaderButton* m_filament{nullptr};
    std::function<void()> m_printer_activated;
    std::function<void()> m_filament_activated;
};

} // namespace Slic3r::GUI::JusPrin
#include "PrinterFilamentChip.hpp"

#include "slic3r/GUI/I18N.hpp"

#include <wx/dcmemory.h>
#include <wx/sizer.h>
#include <algorithm>

namespace Slic3r::GUI::JusPrin {

namespace {
// Neither half may grow past this, so one long preset name cannot push the
// print action off the row. The full text stays available in the tooltip.
constexpr int kHalfLabelCapDip = 240;
} // namespace

PrinterFilamentChip::PrinterFilamentChip(wxWindow* parent, const ShellTheme& theme)
    : wxPanel(parent, wxID_ANY)
{
    SetName("Printer and filament");
    // The halves paint edge to edge; the panel itself is never visible.
    SetBackgroundStyle(wxBG_STYLE_PAINT);
    Bind(wxEVT_PAINT, [](wxPaintEvent&) {});

    m_printer = new HeaderButton(this, theme, HeaderStyle::ChipLeft, wxEmptyString, HeaderIcon::Printer);
    m_printer->SetName("Printer");
    m_printer->set_label_cap(kHalfLabelCapDip);
    m_filament = new HeaderButton(this, theme, HeaderStyle::ChipRight, wxEmptyString, HeaderIcon::None);
    m_filament->SetName("Filament");
    m_filament->set_label_cap(kHalfLabelCapDip);

    m_printer->Bind(wxEVT_BUTTON, [this](wxCommandEvent&) { if (m_printer_activated) m_printer_activated(); });
    m_filament->Bind(wxEVT_BUTTON, [this](wxCommandEvent&) { if (m_filament_activated) m_filament_activated(); });

    // Left and right move between the halves; the halves themselves keep
    // Return and Space, which HeaderButton already handles.
    auto arrows = [](HeaderButton* self, HeaderButton* other) {
        self->Bind(wxEVT_KEY_DOWN, [self, other](wxKeyEvent& event) {
            const int key = event.GetKeyCode();
            if (key == WXK_LEFT || key == WXK_RIGHT) {
                if (self != other) other->SetFocus();
                return;
            }
            event.Skip();
        });
    };
    arrows(m_printer, m_filament);
    arrows(m_filament, m_printer);

    Bind(wxEVT_SIZE, [this](wxSizeEvent& event) { layout(); event.Skip(); });
}

void PrinterFilamentChip::set_printer(const wxString& nickname, const wxString& nozzle, const wxString& tooltip)
{
    const wxString name = nickname.empty() ? _L("Select printer") : nickname;
    m_printer->SetLabel(name);
    HeaderRowDecoration decoration;
    // "X1 Carbon · 0.4" reads as one line.
    decoration.detail        = nozzle;
    decoration.detail_inline = true;
    decoration.trailing      = HeaderIcon::Caret;
    m_printer->set_decoration(std::move(decoration));
    // The tooltip carries the full text the chip may have ellipsized. It says
    // what is selected and nothing about whether it is loaded: the chip makes
    // no claim about the physical machine.
    m_printer->SetToolTip(tooltip.empty() ? name : tooltip);
    InvalidateBestSize();
    layout();
}

void PrinterFilamentChip::set_filaments(const FilamentChipModel& model, const wxString& label, const wxString& tooltip)
{
    m_filament->SetLabel(label.empty() ? _L("Select filament") : label);
    HeaderRowDecoration decoration;
    for (const ChipDot& dot : model.dots)
        decoration.slot_dots.push_back({wxColour(wxString::FromUTF8(dot.colour)), dot.faded});
    if (model.folded > 0)
        decoration.slot_more = wxString::Format("+%d", int(model.folded));
    decoration.small_slot_dots = model.shrunk;
    decoration.trailing        = HeaderIcon::Caret;
    m_filament->set_decoration(std::move(decoration));
    m_filament->SetToolTip(tooltip.empty() ? label : tooltip);
    InvalidateBestSize();
    layout();
}

void PrinterFilamentChip::set_dark(bool dark)
{
    m_printer->set_dark(dark);
    m_filament->set_dark(dark);
    Refresh();
}

wxSize PrinterFilamentChip::DoGetBestSize() const
{
    const wxSize left = m_printer->GetBestSize(), right = m_filament->GetBestSize();
    return {left.x + right.x, std::max(left.y, right.y)};
}

wxBitmap PrinterFilamentChip::snapshot()
{
    const wxBitmap left = m_printer->snapshot(), right = m_filament->snapshot();
    wxBitmap combined(left.GetWidth() + right.GetWidth(), std::max(left.GetHeight(), right.GetHeight()));
    wxMemoryDC dc(combined);
    dc.DrawBitmap(left, 0, 0);
    dc.DrawBitmap(right, left.GetWidth(), 0);
    dc.SelectObject(wxNullBitmap);
    return combined;
}

void PrinterFilamentChip::layout()
{
    const wxSize size = GetClientSize();
    if (size.x <= 0) return;
    // Under pressure the filament half gives up width first: a long preset
    // name, such as a calibrated copy's, ends in its ellipsis (the tooltip
    // has it whole) while the printer keeps its name. The printer yields
    // only past half the chip, so neither half collapses.
    const int wanted_left  = m_printer->GetBestSize().x;
    const int wanted_right = m_filament->GetBestSize().x;
    const int left = wanted_left + wanted_right <= size.x ? wanted_left
                                                          : std::min(wanted_left, std::max(size.x / 2, size.x - wanted_right));
    m_printer->SetSize(0, 0, left, size.y);
    m_filament->SetSize(left, 0, size.x - left, size.y);
}

} // namespace Slic3r::GUI::JusPrin
#include "PrinterMenu.hpp"
#include "SetupCommands.hpp"
#include "ShellController.hpp"
#include "StatusRow.hpp"
#include "slic3r/GUI/JusPrin/Home/HomeWebView.hpp"

#include "libslic3r/PresetBundle.hpp"
#include "slic3r/GUI/GUI_App.hpp"
#include "slic3r/GUI/I18N.hpp"
#include "slic3r/GUI/Plater.hpp"

namespace Slic3r::GUI::JusPrin {

namespace {

wxString nozzle_text(double nozzle) { return wxString::Format("%g mm", nozzle); }

HeaderMenuItem separator()
{
    HeaderMenuItem item;
    item.separator = true;
    item.title     = true; // never focusable; the rule is the whole row
    return item;
}

HeaderMenuItem other_printer(const Home::PrinterEntry& printer)
{
    HeaderMenuItem row;
    row.label = wxString::FromUTF8(printer.name);
    switch (printer.connection_state) {
    case Home::ConnectionState::Online:
        if (printer.state == Home::PrinterState::Printing) {
            row.decoration.status = StatusTone::Busy;
            row.decoration.status_word = _L("Printing");
            if (printer.progress_percent >= 0)
                row.decoration.status_word += wxString::FromUTF8(" \xC2\xB7 ") +
                                              wxString::Format("%d%%", printer.progress_percent);
        } else {
            row.decoration.status = StatusTone::Positive;
            row.decoration.status_word = _L("Idle");
        }
        break;
    case Home::ConnectionState::Offline:
        row.decoration.status = StatusTone::Neutral;
        row.decoration.status_word = _L("Offline");
        break;
    case Home::ConnectionState::Connected:
        // A saved print host can be reached without reporting a live job.
        row.decoration.status = StatusTone::Positive;
        row.decoration.status_word = _L("Connected");
        break;
    case Home::ConnectionState::None:
        row.decoration.status = StatusTone::Neutral;
        row.decoration.status_word = _L("Not connected");
        break;
    }
    return row;
}

} // namespace

PrinterMenu::PrinterMenu(wxWindow* owner, const ShellTheme& theme, bool dark, Plater& plater)
    : m_plater(plater), m_owner(owner), m_theme(theme), m_dark(dark) {}

void PrinterMenu::open(wxWindow* owner, const ShellTheme& theme, bool dark, Plater& plater, HeaderButton& anchor)
{
    auto self = std::make_shared<PrinterMenu>(owner, theme, dark, plater);
    self->m_menu = new HeaderMenu(owner, theme, dark, {});
    show_root(self);
    self->m_menu->open(anchor);
    // No dismiss listener: the row callbacks own the controller, so it lives
    // until the last queued callback has run.
}

void PrinterMenu::show_root(const Ptr& self)
{
    auto* menu = self->m_menu.get();
    if (menu == nullptr) return; // the popup went away; nothing to rebuild
    const auto printer    = SetupCommands::current_printer();
    const auto connection = SetupCommands::printer_connection();
    const auto plates     = SetupCommands::bed_types();

    std::vector<HeaderMenuItem> rows;

    // Row 1: the machine and what it is doing. A state JusPrin cannot observe
    // reads as "Not connected" with a plain consequence, never as a guess and
    // never in a warning colour -- the chip makes no claim about the machine.
    HeaderMenuItem machine;
    machine.label           = printer.nickname.empty() ? _L("No printer selected") : printer.nickname;
    machine.decoration.bold = true;
    machine.enabled         = connection.monitor_available;
    switch (connection.state) {
    case SetupCommands::ConnectionState::Idle:
        machine.decoration.status      = StatusTone::Positive;
        machine.decoration.status_word = _L("Idle");
        machine.decoration.trailing    = HeaderIcon::Monitor;
        break;
    case SetupCommands::ConnectionState::Printing:
        machine.decoration.status      = StatusTone::Busy;
        machine.decoration.status_word = _L("Printing");
        machine.decoration.trailing    = HeaderIcon::Monitor;
        break;
    case SetupCommands::ConnectionState::Offline:
        machine.decoration.status      = StatusTone::Neutral;
        machine.decoration.status_word = _L("Offline");
        machine.decoration.trailing    = HeaderIcon::Monitor;
        break;
    case SetupCommands::ConnectionState::NotConnected:
        machine.decoration.status      = StatusTone::Neutral;
        machine.decoration.status_word = _L("Not connected");
        // Connect… is deferred to a later slice, so the sub-line states the
        // consequence rather than offering an action that would do nothing.
        machine.decoration.sub_label = _L("Prints go to a card.");
        break;
    }
    if (connection.monitor_available)
        machine.invoke = [] { SetupCommands::open_monitor(); };
    rows.push_back(std::move(machine));
    rows.push_back(separator());

    // Read-only: a printer's nozzle is fixed by its parent system profile, and
    // changing it here would mean moving the printer to another parent and
    // deciding which of its own settings follow. Prepare only shows it.
    HeaderMenuItem nozzle;
    nozzle.label             = _L("Nozzle");
    nozzle.decoration.detail = nozzle_text(printer.nozzle);
    nozzle.enabled           = false;
    rows.push_back(std::move(nozzle));

    HeaderMenuItem plate;
    plate.label = _L("Plate");
    for (const auto& choice : plates)
        if (choice.current) plate.decoration.detail = choice.label;
    plate.enabled = !plates.empty();
    if (plate.enabled) {
        plate.decoration.trailing = HeaderIcon::Right;
        plate.keeps_open          = true;
        plate.invoke              = [self] { show_plates(self); };
    }
    rows.push_back(std::move(plate));
    rows.push_back(separator());

    // Home already resolves each saved printer's device or print-host state.
    // Use that same reading here so an unselected printer does not silently
    // become "Idle" just because its profile exists.
    const auto saved = installed_shell()->home_view()->backend().printers();
    bool has_other_printers = false;
    for (const Home::PrinterEntry& entry : saved) {
        if (entry.kind != Home::PrinterKind::Named || entry.name == printer.preset_name)
            continue;
        if (!has_other_printers) {
            HeaderMenuItem title;
            title.label = _L("OTHER PRINTERS");
            title.title = true;
            rows.push_back(std::move(title));
            has_other_printers = true;
        }
        HeaderMenuItem other = other_printer(entry);
        other.invoke = [self, name = entry.name] {
            if (!SetupCommands::select_named_printer(self->m_plater, name))
                return; // Orca kept the current printer, including when its prompt was cancelled.
            if (ShellController* shell = installed_shell())
                shell->status_row()->refresh();
        };
        rows.push_back(std::move(other));
    }
    if (has_other_printers)
        rows.push_back(separator());

    // Printer settings and Add a printer open the printer conversation.
    // Settings are about the selected preset, named as Orca keys it: the
    // header shows a stock profile's model instead, which names no preset.
    // Orca's placeholder is no printer at all, so its settings are adding one.
    const bool placeholder = wxGetApp().preset_bundle->printers.get_selected_preset().is_default;
    HeaderMenuItem settings;
    settings.label  = _L("Printer settings…");
    settings.invoke = [preset = placeholder ? std::string() : printer.preset_name] {
        if (ShellController* shell = installed_shell())
            shell->open_printer_conversation(preset);
    };
    rows.push_back(std::move(settings));

    // A calibration of the first slot's filament on this printer; which test
    // is the assistant's question. Board 1 puts it after Printer settings….
    HeaderMenuItem calibrate;
    calibrate.label   = _L("Calibrate…");
    calibrate.enabled = !placeholder && printer.valid;
    if (calibrate.enabled) {
        const auto slots = SetupCommands::filament_slots();
        calibrate.invoke = [name = std::string(printer.nickname.ToUTF8()),
                            filament = slots.empty() ? std::string() : std::string(slots.front().filament.alias.ToUTF8())] {
            if (ShellController* shell = installed_shell())
                shell->start_calibration(name, filament);
        };
    }
    rows.push_back(std::move(calibrate));

    HeaderMenuItem add;
    add.label  = _L("Add a printer…");
    add.invoke = [] {
        if (ShellController* shell = installed_shell())
            shell->open_printer_conversation();
    };
    rows.push_back(std::move(add));

    menu->replace_items(std::move(rows));
}

void PrinterMenu::show_plates(const Ptr& self)
{
    std::vector<HeaderMenuItem> choices;
    for (const auto& choice : SetupCommands::bed_types()) {
        HeaderMenuItem row;
        row.label            = choice.label;
        row.decoration.check = choice.current;
        row.invoke = [self, value = choice.value] { SetupCommands::select_bed_type(self->m_plater, value); };
        choices.push_back(std::move(row));
    }
    show_sublist(self, _L("Plate"), std::move(choices));
}

void PrinterMenu::show_sublist(const Ptr& self, const wxString& title, std::vector<HeaderMenuItem> choices)
{
    auto* menu = self->m_menu.get();
    if (menu == nullptr) return; // the popup went away; nothing to rebuild
    std::vector<HeaderMenuItem> rows;
    HeaderMenuItem back;
    back.label      = title;
    back.icon       = HeaderIcon::Back;
    back.keeps_open = true;
    back.invoke     = [self] { show_root(self); };
    rows.push_back(std::move(back));
    rows.push_back(separator());
    for (auto& choice : choices) rows.push_back(std::move(choice));
    menu->replace_items(std::move(rows));
}

} // namespace Slic3r::GUI::JusPrin

