        }
        if (!m_decoration.slot_more.empty()) {
            gc->SetFont(detail_font(), p.text_secondary);
            double tw, th; gc->GetTextExtent(m_decoration.slot_more, &tw, &th);
            gc->DrawText(m_decoration.slot_more, at, (h-th)/2);
