#pragma once

// Whether the selected printer profile is one the person set up, and the bed
// a printer profile describes. GUI-free so the rule is testable on its own.

#include "libslic3r/Preset.hpp"

#include <optional>

namespace Slic3r::GUI::JusPrin::Printers {

// A visible user printer profile. Profiles embedded in a project, shipped in
// a bundle, or supplied by a vendor are not printers the person added.
bool is_named_printer(const Preset& preset);

// The printer profile came with something other than the person's own setup:
// a system profile a 3MF named, as OrcaSlicer selects when it opens a file
// saved for another printer. OrcaSlicer's placeholder is no printer at all,
// so it is not marked. Nothing is stored; the header asks on every refresh.
bool printer_from_file(const Preset& preset);

// Width and depth of the bounding box of `printable_area`, in mm; empty when
// the config has no usable area.
struct BedSize { double width{0.}; double depth{0.}; };
std::optional<BedSize> bed_size(const DynamicPrintConfig& config);

} // namespace Slic3r::GUI::JusPrin::Printers
EOF
cat > src/slic3r/GUI/JusPrin/Printers/PrinterOrigin.cpp <<'EOF'
#include "PrinterOrigin.hpp"

#include "libslic3r/BoundingBox.hpp"

namespace Slic3r::GUI::JusPrin::Printers {

bool is_named_printer(const Preset& preset) { return preset.type == Preset::TYPE_PRINTER && preset.is_user() && preset.is_visible; }

bool printer_from_file(const Preset& preset) { return !preset.is_default && !is_named_printer(preset); }

std::optional<BedSize> bed_size(const DynamicPrintConfig& config)
{
    const auto* area = config.option<ConfigOptionPoints>("printable_area");
    if (area == nullptr || area->values.size() < 3)
        return std::nullopt;
    const BoundingBoxf box(area->values);
    const Vec2d size = box.size();
    if (size.x() <= 0. || size.y() <= 0.)
        return std::nullopt;
    return BedSize{size.x(), size.y()};
}

} // namespace Slic3r::GUI::JusPrin::Printers
EOF
