SC=/private/tmp/claude/claude-502/-Users-kenneth-Projects-JusPrin--claude-worktrees-file-printer-chip-mark-5f1921/94e678e1-07ef-409d-8e0f-807cdc0676c2/scratchpad && cp tests/jusprin/test_shell_theme.cpp $SC/test_shell_theme.cpp.keep && cat >> tests/jusprin/test_shell_theme.cpp <<EOF

TEST_CASE("zz render", "[.render]")
{
    wxInitializer wx; wxInitAllImageHandlers();
    const ShellTheme theme = load_packaged_theme();
    auto* frame = new wxFrame(nullptr, wxID_ANY, "rows");
    auto render = [&](const char* file, const wxString& label, HeaderRowDecoration d, bool enabled) {
        auto* row = new HeaderButton(frame, theme, HeaderStyle::Menu, label, HeaderIcon::None);
        row->set_decoration(d); row->Enable(enabled);
        row->SetSize(row->FromDIP(wxSize(320, theme.metrics().menu_row.height + theme.metrics().space_3)));
        row->snapshot(2.0).SaveFile(wxString("$SC/rows/") + file, wxBITMAP_TYPE_PNG);
    };
    HeaderRowDecoration a; a.bold = true; a.status = StatusTone::Neutral; a.status_word = "Not connected";
    a.sub_label = "Prints go to a card."; a.sub_label_role = TextRole::Label; a.sub_label_faint = true;
    render("1-fixed.png", "Bambu Lab A1 mini 2", a, false);
    HeaderRowDecoration b; b.bold = true; b.sub_label = "From the file · not one of your printers";
    b.sub_label_tone = StatusTone::Warning; b.sub_label_role = TextRole::BodySmall;
    render("2-fixed.png", "Bambu Lab P1S", b, false);
    frame->Destroy();
